.adc2{--bg:#050505; --bg-2:#0a0a0a; --card:#121214; --card-2:#18181b; --line:rgba(255,255,255,.10); --line-2:rgba(255,255,255,.18);
  --ink:#f5f5f7; --ink-2:#b8b8c2; --ink-3:#8a8a96;
  --purple:#8b5cf6; --pink:#ec4899; --blue:#3b82f6; --ok:#34d399;
  --note-bg:#fff7d6; --note-ink:#3b2f00; --note-line:#f0c94a;
  --grad:linear-gradient(90deg,#8b5cf6,#ec4899 55%,#3b82f6);
  --f-sans:"Outfit","Noto Sans SC",system-ui,-apple-system,"Segoe UI",sans-serif;
  --f-cn:"Noto Sans SC","PingFang SC","Microsoft YaHei",sans-serif;
  color-scheme:dark;}
:where(.adc2) *{box-sizing:border-box}
@media (prefers-reduced-motion:reduce){:where(.adc2) *{animation:none!important;transition:none!important}}
.adc2{background:var(--bg);color:var(--ink);font-family:var(--f-sans);font-size:16px;line-height:1.6;margin:0}
:where(.adc2) a{color:inherit;text-decoration:none}
:where(.adc2) img{display:block;max-width:100%;height:auto}
:where(.adc2) button{font:inherit;color:inherit}
.adc2 :focus-visible{outline:2px solid var(--pink);outline-offset:3px;border-radius:6px}
.adc2 .wrap{max-width:1240px;margin:0 auto;padding-inline:20px}
:where(.adc2) h1,:where(.adc2) h2,:where(.adc2) h3{margin:0;text-wrap:balance;letter-spacing:-.01em}
:where(.adc2) h2{font-size:clamp(28px,4vw,44px);line-height:1.12;font-weight:700}
:where(.adc2) h3{font-size:18px;font-weight:600;line-height:1.3}
:where(.adc2) p{margin:0}
.adc2 .eyebrow{font-size:13px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--ink-3)}
.adc2 .grad{background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
.adc2 .sec{padding-block:88px;border-top:1px solid var(--line);position:relative}
.adc2 .sec-head{display:flex;flex-direction:column;gap:14px;max-width:760px;margin-bottom:40px}
.adc2 .sec-head p{color:var(--ink-2);font-size:18px}
.adc2 .btn{display:inline-flex;align-items:center;gap:8px;padding:12px 20px;border-radius:999px;font-weight:600;font-size:15px;border:1px solid transparent;cursor:pointer;white-space:nowrap}
.adc2 .btn-primary{background:#fff;color:#0a0a0a}
